                    info!("✅ Using LLM_PROVIDER: {:?}", pt);
                    pt
                } else {
                    warn!("⚠️  LLM_PROVIDER '{}' not available", provider_name);
                    default_provider.unwrap_or(ProviderType::Factory)
                }
            } else {
                warn!("⚠️  Invalid LLM_PROVIDER '{}'", provider_name);
                default_provider.unwrap_or(ProviderType::Factory)
