                          ? "bg-destructive/10 border border-destructive/30 text-destructive"
                          : "bg-card border border-border",
                  )}
                >
                  {msg.role === "tool" && (
                    <div className="text-[10px] text-muted-foreground mb-1.5 font-sans flex items-center gap-1">
                      <Wrench className="h-3 w-3" />
                      {msg.toolName}
                    </div>
                  )}
                  {msg.role === "user" || msg.role === "tool" ? (
                    <div
                      className={cn(
                        "text-sm leading-relaxed whitespace-pre-wrap",
                        msg.role === "tool" && "text-muted-foreground",
                      )}
                    >
                      {msg.content}
                    </div>
                  ) : (
                    <div className="space-y-3">
                      {parseGenerativeBlocks(msg.content).map((seg, i) =>
                        seg.type === "text" ? (
                          <div
                            key={i}
                            className="text-sm leading-relaxed whitespace-pre-wrap"
                          >
                            {seg.text}
                          </div>
                        ) : (
                          <GenerativeBlock
                            key={i}
                            spec={seg.spec}
                            onAction={(action, payload) => {
                              const actionMsg: Message = {
                                id: Date.now().toString(),
                                role: "user",
                                content: `[Action: ${action}] ${JSON.stringify(payload)}`,
                                timestamp: new Date(),
                              };
                              setMessages((prev) => [...prev, actionMsg]);
                            }}
                          />
                        ),
                      )}
                    </div>
                  )}
                  <div
                    className={cn(
                      "text-[10px] mt-1.5",
                      msg.role === "user"
                        ? "text-primary-foreground/60"
                        : "text-muted-foreground",
