              />
              {projections.isFetching ? "Fetching..." : "Live"}
            </span>
          </div>
        </div>
      )}

      {activeTab === "system-prompt" && (
        <div className="flex-1 flex flex-col overflow-hidden">
          <SystemPromptView />
        </div>
      )}
    </div>

