        match p.parse::<ProviderType>() {
            Ok(pt) => Some(pt),
            Err(_) => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(ChatResponse {
                        content: String::new(),
                        provider: p.clone(),
                        model: String::new(),
                        tools_used: None,
                        error: Some(format!("Unknown provider: {}", p)),
                    }),
