            }
        }
    } else {
        None
    };

    // Build messages
    let messages = vec![
        ChatMessage::system("You are a helpful AI assistant integrated with op-dbus, a system management tool. You can help with system administration, code, and general questions."),
        ChatMessage::user(&req.message),
    ];

