import type {
  HealthSnapshot, StatusSummary, DbusService, Tool, Agent, Session,
  ChatMessage, LogEntry, ConfigSnapshot, LlmProvider, LlmModel,
} from "@/types/api";

const BASE = import.meta.env.VITE_API_BASE_URL || "/api";

/** REST fallback for endpoints not yet gRPC-ified */
async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { "Content-Type": "application/json", ...init?.headers },
    ...init,
  });
  const contentType = res.headers.get("content-type") ?? "";
  const body = await res.text();
  const isJson = contentType.includes("application/json");
  const payload = body && isJson ? JSON.parse(body) : body;

  if (!res.ok) {
    const detail =
      payload && typeof payload === "object" && "error" in payload
        ? String((payload as { error?: unknown }).error)
        : body.slice(0, 240);
    throw new Error(`API ${res.status}${detail ? `: ${detail}` : ""}`);
  }

  if (!isJson) {
    throw new Error(
      `API ${res.status} returned ${contentType || "non-JSON"} from ${path}: ${body.slice(0, 120)}`,
    );
  }

  return payload as T;
}

